import { randomUUID } from "node:crypto";

export default function prepareRepurposing({ request }) {
  if (!request || typeof request !== "object" || Array.isArray(request))
    throw new Error("Submit a content object.");
  const content = request.content || request.text || "";
  if (typeof content !== "string" || content.trim().length < 50)
    throw new Error("Content must be at least 50 characters.");
  const title = request.title || "Untitled",
    brandVoice = request.brand_voice || "professional yet approachable";
  if (typeof title !== "string" || typeof brandVoice !== "string")
    throw new Error("Title and brand_voice must be strings.");
  return {
    content,
    title,
    brandVoice,
    requestId: randomUUID(),
    processedAt: new Date().toISOString(),
  };
}

