export default function preparePlatformPrompts({ analysis, title, brandVoice, requestId }) {
  if (!analysis || typeof analysis !== "object" || Array.isArray(analysis))
    throw new Error("The analysis must be a JSON object.");
  for (const name of ["keyPoints", "hashtags", "seoKeywords"])
    if (
      !Array.isArray(analysis[name]) ||
      analysis[name].some((value) => typeof value !== "string" || !value.trim())
    )
      throw new Error("The analysis has invalid " + name + ".");
  if (typeof analysis.coreMessage !== "string" || !analysis.coreMessage.trim())
    throw new Error("The analysis has no core message.");
  return {
    title,
    brandVoice,
    requestId,
    keyPointsJson: JSON.stringify(analysis.keyPoints),
    coreMessage: analysis.coreMessage,
  };
}

