export default function collectPlatformDrafts({
  requestId,
  title,
  twitter,
  linkedin,
  instagram,
  facebook,
}) {
  for (const [name, value] of Object.entries({ twitter, linkedin, instagram, facebook }))
    if (!value || typeof value !== "object" || Array.isArray(value))
      throw new Error(name + " must be a JSON object.");
  if (
    !Array.isArray(twitter.thread) ||
    twitter.thread.length === 0 ||
    twitter.thread.some((value) => typeof value !== "string" || !value.trim())
  )
    throw new Error("The X draft has no complete thread.");
  for (const [name, value] of [
    ["LinkedIn post", linkedin.post],
    ["Instagram caption", instagram.caption],
    ["Facebook post", facebook.post],
  ])
    if (typeof value !== "string" || !value.trim()) throw new Error("The " + name + " is missing.");
  if (
    !Array.isArray(instagram.hashtags) ||
    instagram.hashtags.some((value) => typeof value !== "string" || !value.trim())
  )
    throw new Error("The Instagram hashtags are invalid.");
  const completedAt = new Date().toISOString();
  return {
    values: [
      [
        requestId,
        title,
        completedAt,
        JSON.stringify(twitter.thread),
        linkedin.post,
        instagram.caption,
        facebook.post,
      ],
    ],
    result: {
      success: true,
      requestId,
      title,
      completedAt,
      platforms: ["twitter", "linkedin", "instagram", "facebook"],
      drafts: { twitter, linkedin, instagram, facebook },
      message: "4 platform drafts generated and logged to Google Sheets.",
    },
  };
}
